files.content:
html {
  block-size: 100%;
}

.page {
  display: grid;
  grid-template-columns: minmax(min-content, 1fr) 3fr 3fr;
  grid-template-rows: 9em auto 9em;
  grid-template-areas:
    'header header header header'
    'navigation main main banner'
    'footer footer footer footer';
  min-block-size: 100%;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-weight: 400;
  font-size: 20px;
}

.content {
  grid-area: main;
  padding: 0 1em 6em 0;
  background-color: #fffffb;
}

.content__row {
  display: grid;
  gap: 1em;
}

.content__row_content_auto-fill {
  grid-template-columns: repeat(auto-fill, minmax(70px, 1fr));
}

.content__row_content_auto-fit {
  grid-template-columns: repeat(auto-fit, minmax(70px, 1fr));
}

.sidebar {
  grid-area: navigation;
}

.header {
  display: flex;
  grid-area: header;
  justify-content: space-between;
  align-items: center;
  margin-block-end: 1em;
  border-block-end: 1px solid #ddd;
  padding: 1em;
}

.header__button-wrapper {
  display: flex;
  gap: 6px;
}

.header__button {
  border: 1px solid #000;
  padding: 6px 15px;
  color: white;
  font-size: 12px;
  text-transform: uppercase;
  background-color: #464646;
  cursor: pointer;
}

.header__button_active {
  color: #393939;
  background-color: #ddd;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.footer {
  display: flex;
  grid-area: footer;
  justify-content: space-between;
  align-items: center;
  padding: 0 1em;
  background-color: #000;
}

.footer__copyright {
  margin: 0;
  color: #fff;
  font-weight: 700;
  font-size: 16px;
  font-style: italic;
}

.logo {
  max-inline-size: 100%;
  max-block-size: 100%;
  object-fit: cover;
}

.card__image {
  max-inline-size: 100%;
  object-fit: cover;
}

.navigation__list {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style-type: none;
}

.navigation__link {
  display: block;
  padding: 0 1em 1em;
  color: #0595fc;
  font-weight: bold;
  font-size: 1.2em;
  text-decoration: none;
  text-transform: uppercase;
  transition: color 0.3s;
}

.navigation__link:hover,
.navigation__link:active {
  color: #6dc1fd;
}

.card__list {
  display: flex;
  flex-wrap: wrap;
  padding: 0;
  list-style-type: none;
}

.card__link {
  display: block;
  margin: 5px 30px 0 0;
  padding: 0 3px;
  color: #6dc1fd;
  font-size: 0.9em;
  text-decoration: none;
  transition: color 0.2s, background-color 0.2s;
}

.card__link:hover,
.card__link:active {
  color: #fff;
  background-color: #6dc1fd;
}

.card__title {
  font-weight: 300;
  font-size: 0.8em;
}

.card__description {
  color: #949494;
  font-size: 0.9em;
}

.card__more {
  font-weight: 300;
  font-size: 1.2em;
}

@media (width <= 986px) {
  .page {
    grid-template-rows: 6em auto 6em;
    font-size: 16px;
  }
}
